def cross_pattern(n):
    for i in range(n):                          # check every row
        for j in range(n):                       # check every column in that row
            if i == j or i + j == n - 1:
                print("*", end="")                   # this cell is on one of the two diagonals
            else:
                print(" ", end="")                   # everywhere else stays blank
        print()                                  # move to the next line after the row


if __name__ == "__main__":
    cross_pattern(5)

