        for (int i = 0; i < n; i++) {                  // only the two diagonal columns matter per row
            char[] row = new char[n];
            Arrays.fill(row, ' ');                       // start with a blank row of n spaces
            row[i] = '*';                                 // the main diagonal position
            row[n - 1 - i] = '*';                          // the anti diagonal position
            System.out.println(new String(row));         // one print call per row instead of per character
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.crossPattern(5);
    }
}

