import java.util.*;

public class Main {
    void crossPattern(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char[] row = new char[n];
            Arrays.fill(row, ' ');
            row[i] = '*';
            row[n - 1 - i] = '*';
            sb.append(row);                              // build every row directly, one operation each
            if (i < n - 1) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                        // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.crossPattern(5);
    }
}

